@DisplayName("주문 상태 전이 시나리오")
@TestFactory
Collection<DynamicTest> orderStatusTransition() {
    Order order = Order.create(products, 영업중);

    return List.of(
            dynamicTest("생성된 주문은 INIT 이다", () ->
                    assertThat(order.getOrderStatus()).isEqualTo(INIT)),

            dynamicTest("INIT 에서 결제 완료로 바꿀 수 있다", () -> {
                order.completePayment();
                assertThat(order.getOrderStatus()).isEqualTo(PAYMENT_COMPLETED);
            }),

            dynamicTest("결제 완료에서 바로 완료로는 못 바꾼다", () ->
                    assertThatThrownBy(order::complete)
                            .isInstanceOf(IllegalStateException.class)
                            .hasMessage("수령 전에는 완료할 수 없습니다.")),

            dynamicTest("결제 완료에서 수령으로 바꿀 수 있다", () -> {
                order.receive();
                assertThat(order.getOrderStatus()).isEqualTo(RECEIVED);
            }),

            dynamicTest("수령에서 완료로 바꿀 수 있다", () -> {
                order.complete();
                assertThat(order.getOrderStatus()).isEqualTo(COMPLETED);
            })
    );
}

